(7462072, 1183604, 114285, '<td valign="top">Beautiful once again!</td>', 'Beautiful once again!', '2016-06-29 01:30:37.000000', NULL, 1),
(7462073, 1183418, 114285, '<td valign="top">Great image, stunning acutally, shame it will be DQ for you!</td>', 'Great image, stunning acutally, shame it will be DQ for you!', '2016-06-29 01:32:55.000000', NULL, 1),
(7462076, 1183232, 4877, '<td valign="top">Rovinj Croatia? Beautiful shot.  Love the soft water in the rocks in the foreground.  Would have liked the background a little sharper, but a nice mood overall.</td>', 'Rovinj Croatia? Beautiful shot.  Love the soft water in the rocks in the foreground.  Would have liked the background a little sharper, but a nice mood overall.', '2016-06-29 03:09:20.000000', NULL, 1),
(7462077, 1183418, 77543, '<td valign="top">oops text</td>', 'oops text', '2016-06-29 04:35:04.000000', NULL, 1),
(7462110, 1183506, 12611, '<td valign="top">The sexual tension is high, and the hair is shiny. Good one.</td>', 'The sexual tension is high, and the hair is shiny. Good one.', '2016-06-29 09:29:05.000000', NULL, 1),
(7462113, 1183389, 12611, '<td valign="top">Well set up and executed shot. (alternate title- "Does this Ethereal Faerie Grove make my butt look big? It doesn''t- its just that she is looking down, and well...what a world where we have to explain everything!)</td>', 'Well set up and executed shot. (alternate title- "Does this Ethereal Faerie Grove make my butt look big? It doesn''t- its just that she is looking down, and well...what a world where we have to explain everything!)', '2016-06-29 09:31:21.000000', NULL, 1),
(7462114, 1183434, 12611, '<td valign="top">The particular shade of blue plays beautifully against the clay.</td>', 'The particular shade of blue plays beautifully against the clay.', '2016-06-29 09:32:08.000000', NULL, 1),
(7462115, 1183439, 12611, '<td valign="top">I do like the juxtaposition of the happy little stroll and the giant, looming, scary barn in the background.</td>', 'I do like the juxtaposition of the happy little stroll and the giant, looming, scary barn in the background.', '2016-06-29 09:32:53.000000', NULL, 1),
(7462116, 1183268, 12611, '<td valign="top">Very nice, lingering beauty. What follows is not a criticism of the composition, to the contrary, it may be high praise, but somehow I get the feeling I want to see more here, more grassland, more mountain, more sky.</td>', 'Very nice, lingering beauty. What follows is not a criticism of the composition, to the contrary, it may be high praise, but somehow I get the feeling I want to see more here, more grassland, more mountain, more sky.', '2016-06-29 09:34:57.000000', NULL, 1),
(7462117, 1183283, 12611, '<td valign="top">Beautiful contrast. The dead center horizon helps to keep the  real and reflected piecing through the shot like an arrow...</td>', 'Beautiful contrast. The dead center horizon helps to keep the  real and reflected piecing through the shot like an arrow...', '2016-06-29 09:36:33.000000', NULL, 1),
(7462118, 1183333, 12611, '<td valign="top">cute and beautifully done.</td>', 'cute and beautifully done.', '2016-06-29 09:37:25.000000', NULL, 1),
(7462119, 1183310, 12611, '<td valign="top">an explosion of color for sure. to my untrained eye, there is some center pixelation perhaps from sharpening or structure, but no worries, top notch.</td>', 'an explosion of color for sure. to my untrained eye, there is some center pixelation perhaps from sharpening or structure, but no worries, top notch.', '2016-06-29 09:39:23.000000', NULL, 1),
(7462121, 1183368, 12611, '<td valign="top">I am left oddly uncomfortable by the title, and that makes the whole thing better. (Even the border, which people will no doubt comment upon, as if it was the worst idea since crystal pepsi.)</td>', 'I am left oddly uncomfortable by the title, and that makes the whole thing better. (Even the border, which people will no doubt comment upon, as if it was the worst idea since crystal pepsi.)', '2016-06-29 09:40:56.000000', NULL, 1),
(7462122, 1183293, 12611, '<td valign="top">Beautiful pink tones, and shapes fading away into the mist.</td>', 'Beautiful pink tones, and shapes fading away into the mist.', '2016-06-29 09:41:47.000000', NULL, 1),
(7462123, 1183354, 12611, '<td valign="top">Quite profound, makes us question everything right back to existence, for a brief second.</td>', 'Quite profound, makes us question everything right back to existence, for a brief second.', '2016-06-29 09:42:37.000000', NULL, 1),
