(7463147, 1183570, 54446, '<td valign="top">You''ve captured the solitude and silence of winter very well.  Congrats on your top 10 finish.</td>', 'You''ve captured the solitude and silence of winter very well.  Congrats on your top 10 finish.', '2016-07-06 09:42:29.000000', NULL, 0),
(7463148, 1183225, 54446, '<td valign="top">This was my choice for top image.  Great job of BW conversion.  Very AA-like.  Congrats on your top 10 finish.</td>', 'This was my choice for top image.  Great job of BW conversion.  Very AA-like.  Congrats on your top 10 finish.', '2016-07-06 09:44:14.000000', NULL, 0),
