(7463178, 1183693, 31637, '<td valign="top">Glad the old cam can still kick it in the ass. Nice shot!</td>', 'Glad the old cam can still kick it in the ass. Nice shot!', '2016-07-06 11:47:08.000000', NULL, 0),
(7463181, 1183693, 93283, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by hahn23:</b></div><hr/><i> Interesting detail.  Good management of the light.  Congratulations on your top 10 finish. </i></td></tr></table> <br/> <br/>Hey Richard good to see you are still here... It''s been awhile since I''ve been here... Congrats on your first place image!</td>', 'Originally posted by hahn23: Interesting detail.  Good management of the light.  Congratulations on your top 10 finish.   Hey Richard good to see you are still here... It''s been awhile since I''ve been here... Congrats on your first place image!', '2016-07-06 12:00:23.000000', NULL, 0),
(7463183, 1183693, 93283, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by RulerZigzag:</b></div><hr/><i> Glad the old cam can still kick it in the ass. Nice shot! </i></td></tr></table> <br/> <br/>It does the job outdoors... Indoors, forget about it... Lmao, it''s a noise machine!!!</td>', 'Originally posted by RulerZigzag: Glad the old cam can still kick it in the ass. Nice shot!   It does the job outdoors... Indoors, forget about it... Lmao, it''s a noise machine!!!', '2016-07-06 12:01:47.000000', NULL, 0),
(7463215, 1183461, 37858, '<td valign="top">Congrats on the red ribbon, Dennis.  This is a beautiful, subtle image.  I especially like the soft clouds, but also appreciate the tonal and color differences between the arch rocks and the land mass behind them.</td>', 'Congrats on the red ribbon, Dennis.  This is a beautiful, subtle image.  I especially like the soft clouds, but also appreciate the tonal and color differences between the arch rocks and the land mass behind them.', '2016-07-06 15:49:38.000000', NULL, 0),
(7463216, 1183281, 37858, '<td valign="top">Congrats on the blue.  The whole image is beautiful, but I especially like the balance of the tall trees and moon on the right side offsetting the visual weight of the mountain peak to the left side.</td>', 'Congrats on the blue.  The whole image is beautiful, but I especially like the balance of the tall trees and moon on the right side offsetting the visual weight of the mountain peak to the left side.', '2016-07-06 15:52:26.000000', NULL, 0);
