(7463245, 1183649, 61396, '<td valign="top">a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=100831" rel="nofollow" target="_blank">PennyStreet</a> photo!</td>', 'a  PennyStreet photo!', '2016-07-06 18:10:53.000000', NULL, 0),
(7463263, 1183516, 16148, '<td valign="top">Wish I had taken this.  So much of what I enjoy about photography is in this image.  You stayed out of the way allowing the subject matter to speak for itself. The unknown outside the frame, the tension, and your impeccable timing.  Thank you.</td>', 'Wish I had taken this.  So much of what I enjoy about photography is in this image.  You stayed out of the way allowing the subject matter to speak for itself. The unknown outside the frame, the tension, and your impeccable timing.  Thank you.', '2016-07-06 20:41:59.000000', NULL, 0),
