(7463290, 1183634, 112739, '<td valign="top">Great story! Makes me smile. Congrats on HM!</td>', 'Great story! Makes me smile. Congrats on HM!', '2016-07-06 23:30:13.000000', NULL, 0),
(7463291, 1183331, 112739, '<td valign="top">This was one of my higher scores. Love all the textures and the artistic approach with your lens settings.</td>', 'This was one of my higher scores. Love all the textures and the artistic approach with your lens settings.', '2016-07-06 23:31:44.000000', NULL, 0),
(7463292, 1183577, 112739, '<td valign="top">You''ve combined a lot of fine elements to make an excellent image. It pops right away and that gets your attention and then you can slowly take your time to enjoy all the little things. Congrats on the TT!</td>', 'You''ve combined a lot of fine elements to make an excellent image. It pops right away and that gets your attention and then you can slowly take your time to enjoy all the little things. Congrats on the TT!', '2016-07-06 23:34:59.000000', NULL, 0),
(7463294, 1183509, 112739, '<td valign="top">Guess not too many folks hated this image. Congrats on the TT! I think its a fabulous image although I have to admit the first time I viewed it, I did not see all the things I see now. Wish I would have scored it higher now.</td>', 'Guess not too many folks hated this image. Congrats on the TT! I think its a fabulous image although I have to admit the first time I viewed it, I did not see all the things I see now. Wish I would have scored it higher now.', '2016-07-06 23:38:07.000000', NULL, 0),
(7463295, 1183225, 112739, '<td valign="top">This image caught my attention right away. Very happy to see it in the TT. Congrats!</td>', 'This image caught my attention right away. Very happy to see it in the TT. Congrats!', '2016-07-06 23:39:32.000000', NULL, 0),
(7463296, 1183570, 112739, '<td valign="top">This mono caught my attention right away. Very well done with a strong comp and perfect exposure for the mood. Congrats on TT!</td>', 'This mono caught my attention right away. Very well done with a strong comp and perfect exposure for the mood. Congrats on TT!', '2016-07-06 23:40:37.000000', NULL, 0),
