(7463936, 1183461, 121362, '<td valign="top">Congrats on the red. Great shot.</td>', 'Congrats on the red. Great shot.', '2016-07-11 08:06:09.000000', NULL, 0),
(7463964, 1183685, 19825, '<td valign="top">I found this rather fascinating and thought it had nice energy and negative space. I was surprised to find this way down here. Looking at the number of votes below a significant number of voters were in a different kind of negative space.</td>', 'I found this rather fascinating and thought it had nice energy and negative space. I was surprised to find this way down here. Looking at the number of votes below a significant number of voters were in a different kind of negative space.', '2016-07-11 12:02:00.000000', NULL, 0),
(7463965, 1183252, 19825, '<td valign="top">Really quite fascinating.</td>', 'Really quite fascinating.', '2016-07-11 12:04:00.000000', NULL, 0),
(7463966, 1183254, 19825, '<td valign="top">I found this quite compelling. Unfortunately, some voters have a higher priority on focus than impact. Nicely captured.</td>', 'I found this quite compelling. Unfortunately, some voters have a higher priority on focus than impact. Nicely captured.', '2016-07-11 12:08:07.000000', NULL, 0),
(7463970, 1183356, 19825, '<td valign="top">You have done well to spot interesting light, texture and reflection. I think if you could added an element such as a person halfway down the block crossing the street that might have taken the image up a notch. However, looking at the empty streets, it might have been well past dark if you waited for this to happen by chance...</td>', 'You have done well to spot interesting light, texture and reflection. I think if you could added an element such as a person halfway down the block crossing the street that might have taken the image up a notch. However, looking at the empty streets, it might have been well past dark if you waited for this to happen by chance...', '2016-07-11 12:18:14.000000', NULL, 0),
(7463976, 1183577, 98339, '<td valign="top">I''m so glad to see you on the front page!!!<br/> <br/>Congratulations!!!</td>', 'I''m so glad to see you on the front page!!! Congratulations!!!', '2016-07-11 12:33:06.000000', NULL, 0),
(7464112, 1183461, 156466, '<td valign="top">Fully expected a shot from Patagonia from you Dennis, and you delivered in spades.  Well deserved ribbon.</td>', 'Fully expected a shot from Patagonia from you Dennis, and you delivered in spades.  Well deserved ribbon.', '2016-07-12 09:28:43.000000', NULL, 0),
